<?php
/** Non-destructive structural complexity diagnostics. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\DOM;
final class DOMComplexityAnalyzer {
	public function analyze( string $html ): array { if ( '' === trim( $html ) || ! class_exists( 'DOMDocument' ) ) { return array( 'nodes' => 0, 'max_depth' => 0, 'largest_subtree' => 0, 'repeated_wrappers' => 0, 'elementor_components' => 0, 'woodmart_components' => 0, 'large_hidden_sections' => 0 ); } $doc = new \DOMDocument(); $previous = libxml_use_internal_errors( true ); $doc->loadHTML( $html, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING ); libxml_clear_errors(); libxml_use_internal_errors( $previous ); $stats = array( 'nodes' => 0, 'max_depth' => 0, 'largest_subtree' => 0, 'repeated_wrappers' => 0, 'elementor_components' => 0, 'woodmart_components' => 0, 'large_hidden_sections' => 0 ); $wrappers = array(); $walk = function ( \DOMNode $node, int $depth ) use ( &$walk, &$stats, &$wrappers ): int { $count = 1; if ( XML_ELEMENT_NODE === $node->nodeType ) { ++$stats['nodes']; $stats['max_depth'] = max( $stats['max_depth'], $depth ); $class = $node->attributes && $node->attributes->getNamedItem( 'class' ) ? $node->attributes->getNamedItem( 'class' )->nodeValue : ''; if ( false !== strpos( $class, 'elementor-' ) ) { ++$stats['elementor_components']; } if ( false !== strpos( $class, 'wd-' ) ) { ++$stats['woodmart_components']; } $key = $node->nodeName . ':' . trim( $class ); if ( '' !== trim( $class ) ) { $wrappers[ $key ] = ( $wrappers[ $key ] ?? 0 ) + 1; } } foreach ( $node->childNodes as $child ) { $count += $walk( $child, $depth + 1 ); } if ( XML_ELEMENT_NODE === $node->nodeType ) { $stats['largest_subtree'] = max( $stats['largest_subtree'], $count ); $style = $node->attributes && $node->attributes->getNamedItem( 'style' ) ? strtolower( $node->attributes->getNamedItem( 'style' )->nodeValue ) : ''; if ( $count > 50 && ( false !== strpos( $style, 'display:none' ) || false !== strpos( $style, 'display: none' ) || $node->attributes->getNamedItem( 'hidden' ) ) ) { ++$stats['large_hidden_sections']; } } return $count; }; $walk( $doc, 0 ); $stats['repeated_wrappers'] = count( array_filter( $wrappers, static function ( int $count ): bool { return $count >= 5; } ) ); return $stats; }
}
